import type { Worker } from 'bullmq';
import { logger } from './logger';

// The worker drains jobs on SIGTERM with a 30 second grace period:
// stop taking new jobs, let in-flight jobs finish, then exit.
// Anything still running after 30s is abandoned and BullMQ marks it stalled.
const GRACE_PERIOD_MS = 30_000;

export function installShutdown(workers: Worker[]) {
  let shuttingDown = false;
  process.on('SIGTERM', async () => {
    if (shuttingDown) return;
    shuttingDown = true;
    logger.info({ workers: workers.length }, 'SIGTERM received, draining');

    const timer = setTimeout(() => {
      logger.warn('grace period elapsed, exiting with jobs in flight');
      process.exit(1);
    }, GRACE_PERIOD_MS);

    await Promise.all(workers.map((w) => w.close()));
    clearTimeout(timer);
    process.exit(0);
  });
}

