import type { Queue } from 'bullmq';

// Cron jobs are BullMQ repeatable jobs defined in src/schedules.ts (this file).
// There is no system cron or k8s CronJob: on boot each worker upserts these
// schedulers, and BullMQ makes sure only one instance fires per tick.
export async function registerSchedules(queues: { maintenance: Queue; email: Queue; billing: Queue }) {
  await queues.billing.upsertJobScheduler('billing-sync', { every: 15 * 60 * 1000 }, { name: 'billing-sync' });

  await queues.email.upsertJobScheduler(
    'nightly-digest',
    { pattern: '0 6 * * *', tz: 'America/Toronto' },
    { name: 'nightly-digest' },
  );

  await queues.maintenance.upsertJobScheduler(
    'purge-soft-deleted',
    { pattern: '30 3 * * 0', tz: 'UTC' },
    { name: 'purge-soft-deleted' },
  );
}

